 (page.locator('.global-search').tap() if page.viewport_size['width']<781 else page.keyboard.press('Control+k'));page.wait_for_selector('.quick-switcher[open]');page.locator('#command-query').fill(query);page.wait_for_function("document.querySelector('#command-results')?.getAttribute('aria-busy')==='false'");return dlg(page)
