  action(page,'ex-appearance');count=page.locator('dialog[open]').count();page.keyboard.press('Control+k');page.wait_for_timeout(80);assert page.locator('dialog[open]').count()==count;assert page.locator('.quick-switcher[open]').count()==0;close(page);dismiss(page);ok('Quick switcher does not replace an existing unsaved form')
  # Actual saved view and filters through visible controls.
  action(page,'ex-save');d=dlg(page);d.locator('[name=name]').fill('Refinement register');d.locator('[type=submit]').click();page.wait_for_timeout(130);columns=page.evaluate('Civora.explorer.configuration.columns');page.locator('#state-filter').select_option('Work in progress');assert page.locator('[data-kind=state]').count()==1;assert page.locator('.ex-view-dirty').inner_text()=='Unsaved view changes';action(page,'ex-clear');assert page.evaluate('Civora.explorer.configuration.columns')==columns;assert page.locator('[data-kind=state]').count()==0;ok('Filter chips identify unsaved view changes and clearing filters preserves register columns')
