  page.evaluate('(s)=>Civora.explorer.copyDialog([s.a,s.b])',seed);d=dlg(page);assert d.locator('[type=submit]').is_disabled();d.locator('[name=copy-folder]').select_option(seed['folder']);d.locator('[data-copy-suggest]').click();d.locator('[name=copy-references]').select_option('selected');d.locator('[name=copy-reason]').fill('Prepare an alternative station layout for coordination');assert d.locator('[data-copy-source]').count()==2;page.screenshot(path=str(OUT/'copy-editor.png'),full_page=True);ok('Controlled-copy editor offers destination, exact stored revisions, collision-safe naming and explicit reference policy')
  d.locator('[data-copy-validate]').click();page.wait_for_function('!document.querySelector(".copy-dialog [type=submit]").disabled');assert d.locator('.copy-preview-table tbody tr').count()==2;assert '1 remapped' in d.locator('[data-copy-preview]').inner_text();revision=page.evaluate('Civora.engine.state.revision');page.screenshot(path=str(OUT/'copy-validation.png'),full_page=True);ok('Preview uses the actual command engine and shows allocated numbers with selected-reference remapping')
  d.locator('[data-copy-title]').first.fill('Changed after preview');assert d.locator('[type=submit]').is_disabled();d.locator('[data-copy-validate]').click();page.wait_for_function('!document.querySelector(".copy-dialog [type=submit]").disabled');assert page.evaluate('Civora.engine.state.revision')==revision;d.locator('[type=submit]').click();page.wait_for_function('!document.querySelector(".copy-dialog[open]")');assert page.evaluate('Civora.engine.state.revision')==revision+1
  copied=page.evaluate('(s)=>Civora.engine.state.documents.filter(d=>d.folderId===s.folder)',seed);assert len(copied)==2;assert copied[0]['state']=='Work in progress';assert copied[0]['references']==[copied[1]['id']];assert page.evaluate('Civora.ui.selection.size')==2;assert page.evaluate('(id)=>Civora.engine.repository.blob(Civora.engine.state.documents.find(d=>d.id===id).versions[0].blobId).then(b=>b.text())',copied[0]['id'])=='Design alternative original A\n';ok('Changing inputs invalidates preview; applying creates one atomic verified batch and selects the new documents')
  # Duplicate safe names at the already occupied destination; source versions are retained.
  page.evaluate('(s)=>Civora.explorer.copyDialog([s.a])',seed);d=dlg(page);d.locator('[name=copy-folder]').select_option(seed['folder']);d.locator('[data-copy-suggest]').click();assert ' - copy' in d.locator('[data-copy-name]').input_value();d.locator('[name=copy-reason]').fill('Stale preview test');d.locator('[data-copy-validate]').click();page.wait_for_function('!document.querySelector(".copy-dialog [type=submit]").disabled');page.evaluate('async(s)=>Civora.engine.run("document.update",{id:s.a,title:"Source changed after preview"})',seed);revision=page.evaluate('Civora.engine.state.revision');d.locator('[type=submit]').click();page.wait_for_timeout(80);assert 'workspace changed' in d.locator('.form-error').inner_text().lower();assert page.evaluate('Civora.engine.state.revision')==revision;close(page);ok('Live source changes invalidate an approved copy without creating a prefix or consuming numbering')
  # Mobile actual dialogs, real commands, CSS/touch dimensions. No physical device claim.
  page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(100);dismiss(page);d=palette(page,'alternative');page.screenshot(path=str(OUT/'mobile-search.png'),full_page=True);assert d.bounding_box()['width']<=390;assert page.evaluate('document.documentElement.scrollWidth')<=390;assert d.locator('#command-query').evaluate('(e)=>parseFloat(getComputedStyle(e).fontSize)')>=16;d.locator('[data-quick-kind=folder]').tap();page.wait_for_timeout(80);assert d.locator('[role=option]').count()==1;d.locator('[role=option]').tap();page.wait_for_timeout(100);assert page.evaluate('Civora.ui.folderId')==seed['folder'];ok('Phone search uses touch-friendly controls and opens folders without page-width overflow')
  page.evaluate('(s)=>Civora.explorer.copyDialog([s.a,s.b])',seed);d=dlg(page);assert d.bounding_box()['width']<=390;assert page.evaluate('document.documentElement.scrollWidth')<=390;d.locator('[name=copy-reason]').fill('Phone layout reuse');d.locator('[data-copy-validate]').tap();page.wait_for_function('!document.querySelector(".copy-dialog [type=submit]").disabled');page.screenshot(path=str(OUT/'mobile-copy.png'),full_page=True);assert d.locator('[type=submit]').bounding_box()['height']>=40;close(page);ok('Phone controlled-copy form stacks inputs, validates the real batch and retains a reachable confirmation action')
  page.set_viewport_size({'width':1540,'height':960});page.wait_for_timeout(100);action(page,'ex-menu','[data-menu=View]');action(page,'toggle-theme');d=palette(page,'>');page.screenshot(path=str(OUT/'dark-search.png'),full_page=True);close(page);dismiss(page);page.screenshot(path=str(OUT/'refined-dark.png'),full_page=True);assert not errors,errors;ok('New components share dark appearance and complete without page errors')
